(() => {
    const s = __rhf.game.state;
    return 'look ' + JSON.stringify(s.look) + ', owned ' + JSON.stringify(s.wardrobe) + ', money ' + s.money;
  })()

(() => {
    const g = __rhf.game;
    g.screens.close();
    // the sleeves wear the shirt as a picture on the cloth: the Hawaiian
    // teal (0x19b8c4) must be in it
    const img = g.viewmodel.clothMat.map.image;
    const px = img.getContext('2d').getImageData(0, 0, img.width, img.height).data;
    let teal = 0;
    for (let i = 0; i < px.length; i += 4) if (px[i] < 60 && px[i + 1] > 150 && px[i + 2] > 160) teal++;
    // and the rod hand wears the cloth
    const sleeve = g.viewmodel.rodHand.children[1];
    // the save keeps the look
    g.save && g.save();
    const raw = localStorage.getItem('rubenHotrodFishing.save.v1');
    const d = raw ? JSON.parse(raw) : {};
    return 'teal pixels on the sleeve cloth ' + teal + ' of ' + px.length / 4 + ', rod hand sleeve wears it ' + (sleeve.material.map === g.viewmodel.clothMat.map) + '; saved look ' + JSON.stringify(d.look) + ', saved wardrobe ' + JSON.stringify(d.wardrobe);
  })()

(() => {
    const g = __rhf.game;
    __rhf.session.enterCar();
    g.hotrod.camMode = 'chase';
    return 'in the car, driver shown ' + g.hotrod.driver.visible;
  })()

(() => {
